-- PREPARED ONLY: local review artifact. NOT RUN. No approval to apply to D1 or deploy.
-- Keeps D1 in step with frontend/data/tools.json for slack.com (9 Nov 2026 wording batch),
-- so a later generate-tools-json / refresh-site does not revert the two added quotes and source.
-- Verdict, badge and every other column are unchanged. Guard binds to the 8 Nov row.
SELECT 'before_snapshot' AS snapshot, * FROM tools WHERE domain='slack.com';
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='slack.com' AND compliance_status='compliant_with_caveats' AND summary='"We do not develop generative AI models using Customer Data. To develop predictive models for features such as emoji and channel recommendations, our systems analyse Customer Data (e.g. messages, content and files) submitted to Slack as well as Other Information (including usage information)" "If you want to exclude your Customer Data from helping to train Slack global models, you can opt out." "To opt out, please have your org, workspace owners or primary owner contact our Customer Experience team at feedback@slack.com with your workspace/org URL and the subject line ''Slack global model opt-out request''." "Slack will not use Customer Data to train generative AI models unless Customer provides affirmative opt-in consent." Global predictive-model training is on by default; the workspace-level opt-out must be requested by an owner. Slack does not distinguish free vs paid here. Source has no page date; fetched 8 November 2026.')=1 THEN 'ok: slack.com' ELSE json('GUARD FAILED: slack.com has changed; review again') END AS guard_target;
UPDATE tools SET summary='"We do not develop generative AI models using Customer Data. To develop predictive models for features such as emoji and channel recommendations, our systems analyse Customer Data (e.g. messages, content and files) submitted to Slack as well as Other Information (including usage information)" "If you want to exclude your Customer Data from helping to train Slack global models, you can opt out." "To opt out, please have your org, workspace owners or primary owner contact our Customer Experience team at feedback@slack.com with your workspace/org URL and the subject line ''Slack global model opt-out request''." "Slack will not use Customer Data to train generative AI models unless Customer provides affirmative opt-in consent." "Slack aggregates and disassociates Customer Data such that Slack''s use of Customer Data to update the Services will never identify any of our customers or individuals as the source of any of these improvements to any third party, other than to Slack''s affiliates or sub-processors." Security for AI features in Slack: "Customer data never leaves Slack-controlled infrastructure and is never used to train large language models (LLMs)." Global predictive-model training is on by default; the workspace-level opt-out must be requested by an owner. Slack does not distinguish free vs paid here. Sources have no page date; privacy principles fetched 8 November 2026 and re-checked 9 November 2026; Security for AI features fetched 9 November 2026.',
  source_urls='["https://slack.com/intl/en-gb/trust/data-management/privacy-principles", "https://slack.com/intl/en-gb/help/articles/28310650165907-Security-for-AI-features-in-Slack"]',
  last_checked_at='2026-11-09T08:53:00.000Z',
  last_check_note=NULL,
  manual_override=1,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE domain='slack.com' AND compliance_status='compliant_with_caveats';
SELECT 'after' AS snapshot, domain, compliance_status, manual_override, summary, source_urls, last_checked_at FROM tools WHERE domain='slack.com';
